const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;

const fail = (error) => ({ json: { valid: false, ok: false, error } });

let nombreArchivo = typeof body.nombreArchivo === 'string'
  ? body.nombreArchivo.trim()
  : 'documento.pdf';

nombreArchivo = nombreArchivo
  .split(/[\\/]/)
  .pop()
  .replace(/[\r\n\u0000-\u001f\u007f"]/g, '_')
  .slice(0, 180);

if (!nombreArchivo) nombreArchivo = 'documento.pdf';
if (!/\.pdf$/i.test(nombreArchivo)) nombreArchivo += '.pdf';

const rawValue = typeof body.data === 'string' ? body.data.trim() : '';
const cleanBase64 = rawValue
  .replace(/^data:application\/pdf;base64,/i, '')
  .replace(/\s/g, '');

if (!cleanBase64) {
  return fail('Falta el PDF en base64 dentro del campo data.');
}

if (!/^[A-Za-z0-9+/]*={0,2}$/.test(cleanBase64) || cleanBase64.length % 4 === 1) {
  return fail('El campo data no contiene un base64 valido.');
}

const unpadded = cleanBase64.replace(/=+$/, '');
const padded = unpadded + '='.repeat((4 - (unpadded.length % 4)) % 4);
const pdfBuffer = Buffer.from(padded, 'base64');
const canonicalBase64 = pdfBuffer.toString('base64');

if (canonicalBase64.replace(/=+$/, '') !== unpadded) {
  return fail('El campo data no supera la validacion base64.');
}

if (pdfBuffer.subarray(0, 5).toString('ascii') !== '%PDF-') {
  return fail('El archivo recibido no tiene una cabecera PDF valida.');
}

const MAX_PDF_BYTES = 20 * 1024 * 1024;
if (pdfBuffer.length === 0 || pdfBuffer.length > MAX_PDF_BYTES) {
  return fail('El PDF esta vacio o supera el limite de 20 MB.');
}

return {
  json: {
    valid: true,
    nombreArchivo,
    data: canonicalBase64,
    pdfSize: pdfBuffer.length
  }
};

// Entrada: un PDF en item.binary.data.
// Salida: un item con page_1, page_2, etc. como binarios JPG.

const items = $input.all();
const outputItems = [];
const MAX_PAGES = 100;

for (let index = 0; index < items.length; index++) {
  const item = items[index];

  if (!item.binary?.data) {
    throw new Error('No se encontro el PDF en binary.data.');
  }

  const pdfBuffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  const binaryMeta = item.binary.data || {};
  const pdfFileName = binaryMeta.fileName || item.json?.nombreArchivo || `document_${index + 1}.pdf`;
  const pdfMimeType = binaryMeta.mimeType || 'application/pdf';
  const baseName = (pdfFileName.replace(/\.pdf$/i, '') || 'document').trim();
  const aggregatedBinary = {};
  let pagesConverted = 0;

  for (let page = 1; page <= MAX_PAGES; page++) {
    const boundary = '----n8nFormBoundary' + Math.random().toString(16).slice(2);
    const CRLF = '\r\n';
    const parts = [];

    const addField = (name, value) => {
      parts.push(
        `--${boundary}${CRLF}` +
        `Content-Disposition: form-data; name=\"${name}\"${CRLF}${CRLF}` +
        `${value}${CRLF}`
      );
    };

    addField('format', 'jpg');
    addField('width', '1920');
    addField('height', '2096');
    addField('page', String(page));

    const fileHeader =
      `--${boundary}${CRLF}` +
      `Content-Disposition: form-data; name=\"file\"; filename=\"${pdfFileName}\"${CRLF}` +
      `Content-Type: ${pdfMimeType}${CRLF}${CRLF}`;

    const closing = `${CRLF}--${boundary}--${CRLF}`;
    const preBuffer = Buffer.from(parts.join('') + fileHeader, 'utf8');
    const postBuffer = Buffer.from(closing, 'utf8');
    const requestBody = Buffer.concat([preBuffer, pdfBuffer, postBuffer]);

    let response;
    try {
      response = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://pdf2img-pdf2img-1:3000/convert',
        headers: {
          'Content-Type': `multipart/form-data; boundary=${boundary}`
        },
        body: requestBody,
        json: false,
        encoding: 'arraybuffer',
        timeout: 120000
      });
    } catch (error) {
      if (page === 1) throw error;

      const status =
        error.response?.status ||
        error.httpCode ||
        error.statusCode ||
        error.status;

      if (Number(status) === 400) break;
      throw error;
    }

    const imageBuffer = Buffer.isBuffer(response) ? response : Buffer.from(response);
    if (imageBuffer.length === 0) {
      throw new Error(`La pagina ${page} se convirtio en una imagen vacia.`);
    }

    const jpgFileName = `${baseName}_page_${page}.jpg`;
    aggregatedBinary[`page_${page}`] = {
      data: imageBuffer.toString('base64'),
      mimeType: 'image/jpeg',
      fileName: jpgFileName,
      fileExtension: 'jpg'
    };

    pagesConverted++;
  }

  if (pagesConverted === 0) {
    throw new Error('El PDF no produjo ninguna imagen.');
  }

  outputItems.push({
    json: {
      sourceFileName: pdfFileName,
      originalItemIndex: index,
      pagesConverted,
      binaryKeys: Object.keys(aggregatedBinary)
    },
    binary: aggregatedBinary
  });
}

return outputItems;

// Convierte los binarios internos de n8n en un contrato JSON transportable.
const items = $input.all();
const responses = [];

for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
  const item = items[itemIndex];
  const keys = Array.isArray(item.json?.binaryKeys)
    ? item.json.binaryKeys
    : Object.keys(item.binary || {});

  const binary = {};

  for (const key of keys) {
    const metadata = item.binary?.[key] || {};
    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);

    binary[key] = {
      data: buffer.toString('base64'),
      mimeType: metadata.mimeType || 'image/jpeg',
      fileName: metadata.fileName || `${key}.jpg`,
      fileExtension: metadata.fileExtension || 'jpg'
    };
  }

  responses.push({
    ok: true,
    contractVersion: 1,
    sourceFileName: item.json?.sourceFileName || null,
    originalItemIndex: item.json?.originalItemIndex ?? itemIndex,
    pagesConverted: keys.length,
    binaryKeys: keys,
    binary
  });
}

if (responses.length !== 1) {
  throw new Error('La API esperaba exactamente un PDF procesado.');
}

return { json: responses[0] };
